bool StructTraits<::arc::mojom::CameraDeviceInfo::DataView, ::arc::mojom::CameraDeviceInfoPtr>::Read(
    ::arc::mojom::CameraDeviceInfo::DataView input,
    ::arc::mojom::CameraDeviceInfoPtr* output) {
  bool success = true;
  ::arc::mojom::CameraDeviceInfoPtr result(::arc::mojom::CameraDeviceInfo::New());
  
      if (success && !input.ReadDevicePath(&result->device_path))
        success = false;
      if (success && !input.ReadUsbVid(&result->usb_vid))
        success = false;
      if (success && !input.ReadUsbPid(&result->usb_pid))
        success = false;
      if (success)
        result->lens_facing = input.lens_facing();
      if (success)
        result->sensor_orientation = input.sensor_orientation();
      if (success)
        result->frames_to_skip_after_streamon = input.frames_to_skip_after_streamon();
      if (success)
        result->horizontal_view_angle_16_9 = input.horizontal_view_angle_16_9();
      if (success)
        result->horizontal_view_angle_4_3 = input.horizontal_view_angle_4_3();
      if (success && !input.ReadLensInfoAvailableFocalLengths(&result->lens_info_available_focal_lengths))
        success = false;
      if (success)
        result->lens_info_minimum_focus_distance = input.lens_info_minimum_focus_distance();
      if (success)
        result->lens_info_optimal_focus_distance = input.lens_info_optimal_focus_distance();
      if (success)
        result->vertical_view_angle_16_9 = input.vertical_view_angle_16_9();
      if (success)
        result->vertical_view_angle_4_3 = input.vertical_view_angle_4_3();
  *output = std::move(result);
  return success;
}


